  background: var(--line);
}

.system-column {
  min-height: 280px;
  padding: 22px;
  background: #fff;
  display: grid;
  align-content: start;
  gap: 12px;
}

.system-column strong {
  color: var(--text-95);
  margin-bottom: 8px;
}

.system-column span {
  border: 1px solid var(--line);
  border-radius: var(--r8);
  padding: 10px;
  color: var(--text-65);
  background: #f9fbff;
