}

.ticket-header strong {
  color: var(--brand-blue);
}

.ticket-row span {
  color: var(--text-45);
  font-size: 13px;
  font-weight: 800;
}

.ticket-row strong {
  color: var(--text-95);
}

.media-shelf {
  display: grid;
