  align-content: end;
  gap: 12px;
}

.media-shelf div:nth-child(2) {
  background: var(--surface-blue);
}

.media-shelf strong {
  color: var(--text-95);
}

.media-shelf span {
  color: var(--text-65);
  line-height: 1.52;
}

.routing-canvas {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
