  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  padding: 26px;
  text-align: center;
}

.evolution-center span {
  color: var(--brand-blue);
  font-weight: 800;
}

.evolution-center strong {
  font-size: 28px;
  line-height: 1.18;
}

.evolution-lane {
  padding: 22px;
}

.evolution-lane.orders {
  grid-column: 1 / span 3;
  grid-row: 1;
}

.evolution-lane.data {
  grid-column: 4 / span 3;
  grid-row: 1;
}

.evolution-lane.delivery {
  grid-column: 1 / span 2;
  grid-row: 3;
}

.evolution-lane.connector {
  grid-column: 5 / span 2;
  grid-row: 3;
}

.evolution-lane.service {
  grid-column: 2 / span 4;
  grid-row: 4;
  background: var(--surface-blue);
}

.trust-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: 44px;
  align-items: center;
}

.trust-band {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  overflow: hidden;
  background: var(--line);
}

.trust-band div {
  min-height: 130px;
  padding: 22px;
  background: var(--surface);
  display: grid;
  align-content: center;
  gap: 10px;
}

.trust-band strong {
  color: var(--brand-blue);
  font-size: 28px;
  line-height: 1.12;
}

.trust-band span {
  color: var(--text-65);
}

.capability-intro {
  background: #fff;
}

.capability-intro .lead {
  max-width: 760px;
}

.capability-split {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: 48px;
  align-items: center;
}

.capability-split.reverse {
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
}

.resource-capability,
.about-capability {
  background: var(--page);
}

.resource-capability:nth-of-type(even),
.about-capability:nth-of-type(even) {
  background: #fff;
}

.access-board,
.faq-board,
.ticket-board,
.media-shelf,
.routing-canvas,
.order-workbench,
.reconcile-board,
.dispatch-map,
.connector-topology,
.service-lifecycle {
  border: 1px solid var(--line);
  border-radius: var(--r8);
  background: var(--surface);
  box-shadow: 0 22px 60px rgba(22, 35, 61, 0.08);
}

.access-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  overflow: hidden;
  background: var(--line);
}

.system-column {
  min-height: 280px;
  padding: 22px;
  background: #fff;
  display: grid;
  align-content: start;
  gap: 12px;
}

.system-column strong {
  color: var(--text-95);
  margin-bottom: 8px;
}

.system-column span {
  border: 1px solid var(--line);
  border-radius: var(--r8);
  padding: 10px;
  color: var(--text-65);
  background: #f9fbff;
}

.connector-column {
  background: var(--surface-blue);
}

.connector-column span {
  background: white;
  color: var(--brand-blue);
  font-weight: 800;
}

.faq-board {
  padding: 24px;
  display: grid;
  gap: 14px;
}

.faq-board div {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 8px 14px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--r8);
  background: #fbfcff;
}

.faq-board span {
  grid-row: span 2;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: var(--r8);
  background: var(--navy);
  color: white;
  font-size: 12px;
  font-weight: 800;
}

.faq-board strong,
.industry-map strong {
  color: var(--text-95);
}

.faq-board p {
  margin: 0;
  color: var(--text-65);
  line-height: 1.6;
}

.industry-map {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1px;
  border: 1px solid var(--line);
  border-radius: var(--r8);
  overflow: hidden;
  background: var(--line);
}

.industry-map a {
  min-height: 190px;
  padding: 20px;
  display: grid;
  align-content: space-between;
  gap: 18px;
  background: #fff;
}

.industry-map a:nth-child(odd) {
  background: var(--surface-blue);
}

.industry-map span {
  color: var(--text-65);
  line-height: 1.5;
}

.ticket-board {
  padding: 0;
  overflow: hidden;
}

.ticket-header,
.ticket-row {
  display: grid;
  grid-template-columns: 150px 1fr;
  gap: 16px;
  align-items: center;
  padding: 18px 22px;
  border-bottom: 1px solid var(--line);
}

.ticket-header {
  background: var(--navy);
  color: white;
}

.ticket-header strong {
  color: var(--brand-blue);
}

.ticket-row span {
  color: var(--text-45);
  font-size: 13px;
  font-weight: 800;
}

.ticket-row strong {
  color: var(--text-95);
}

.media-shelf {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  overflow: hidden;
  background: var(--line);
}

.media-shelf div {
  min-height: 220px;
  padding: 22px;
  background: #fff;
  display: grid;
  align-content: end;
  gap: 12px;
}

.media-shelf div:nth-child(2) {
  background: var(--surface-blue);
}

.media-shelf strong {
  color: var(--text-95);
}

.media-shelf span {
  color: var(--text-65);
  line-height: 1.52;
}

.routing-canvas {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
  overflow: hidden;
  margin-bottom: 24px;
  background: var(--line);
}

.routing-canvas div {
  min-height: 180px;
  padding: 18px;
  background: #fff;
  display: grid;
  align-content: start;
  gap: 12px;
}

.routing-canvas div:last-child {
  background: var(--brand-blue);
  color: white;
}

.routing-canvas div:last-child span {
  color: rgba(255, 255, 255, 0.78);
}

.routing-canvas strong {
  color: inherit;
}

.routing-canvas span {
  color: var(--text-65);
  line-height: 1.48;
}

.order-workbench {
  overflow: hidden;
}

.workbench-toolbar {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--line);
}

.workbench-toolbar span,
.workbench-toolbar strong {
  padding: 14px;
  background: var(--navy);
  color: white;
  font-size: 13px;
}

.workbench-toolbar strong {
  color: var(--brand-blue);
}

.order-row {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr 0.9fr;
  gap: 14px;
  align-items: center;
  padding: 18px;
  border-bottom: 1px solid var(--line);
}

.order-row span {
  color: var(--text-65);
}

.order-row strong {
  width: fit-content;
  border-radius: var(--r8);
  background: var(--surface-blue);
  color: var(--brand-blue);
  padding: 8px 10px;
}

.order-row em {
  color: var(--text-45);
  font-style: normal;
}

.order-row.alert {
  background: #fff8f2;
}

.reconcile-board {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 24px;
  padding: 24px;
}

.chart-bars {
  min-height: 260px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  align-items: end;
  border: 1px solid var(--line);
  border-radius: var(--r8);
  padding: 18px;
  background: #f9fbff;
}

.chart-bars span {
  display: block;
  min-height: 36px;
  border-radius: var(--r8) var(--r8) 0 0;
  background: var(--brand-blue);
}

.reconcile-table {
  display: grid;
  align-content: center;
  gap: 12px;
}

.reconcile-table div {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
}

.reconcile-table span {
  color: var(--text-65);
}

.reconcile-table strong {
  color: var(--brand-blue);
}

.dispatch-map {
  position: relative;
  min-height: 360px;
  overflow: hidden;
  background: #f8fbff;
}

.map-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--line) 1px, transparent 1px),
    linear-gradient(90deg, var(--line) 1px, transparent 1px);
  background-size: 42px 42px;
}

.pin {
  position: absolute;
  border-radius: var(--r8);
  padding: 10px 12px;
  background: var(--surface);
  color: var(--text-95);
  box-shadow: 0 12px 30px rgba(22, 35, 61, 0.14);
  font-weight: 800;
}

.pin.store {
  left: 12%;
  top: 22%;
}

.pin.rider {
  right: 18%;
  top: 38%;
}

.pin.third {
  left: 42%;
  bottom: 28%;
  color: var(--brand-blue);
}

.dispatch-status {
  position: absolute;
  left: 24px;
  right: 24px;
  bottom: 24px;
  border-radius: var(--r8);
  background: rgba(255, 255, 255, 0.92);
  padding: 18px;
  display: grid;
  gap: 8px;
}

.dispatch-status strong {
  color: var(--brand-blue);
}

.dispatch-status span {
  color: var(--text-65);
}

.connector-topology {
  min-height: 360px;
  padding: 22px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  align-items: center;
}

.connector-topology span,
.connector-topology strong {
  min-height: 76px;
  border-radius: var(--r8);
  display: grid;
  place-items: center;
  padding: 12px;
  text-align: center;
}

.connector-topology span {
  border: 1px solid var(--line);
  color: var(--text-65);
  background: #f9fbff;
}

.connector-topology strong {
  grid-column: 2;
  grid-row: 1 / span 3;
  min-height: 230px;
  background: var(--brand-blue);
  color: white;
}

.service-lifecycle {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  overflow: hidden;
  background: var(--line);
}

.service-lifecycle div {
  min-height: 220px;
  padding: 22px;
  background: #fff;
  display: grid;
  align-content: space-between;
  gap: 18px;
}

.service-lifecycle div:nth-child(even) {
  background: var(--surface-blue);
}

.service-lifecycle strong {
  color: var(--text-95);
  font-size: 22px;
}

.service-lifecycle span {
  color: var(--text-65);
  line-height: 1.56;
}

.mobile-only {
  display: none;
}


/* T30 real-content restoration */
.page-card-realized {
  display: grid;
  gap: 12px;
}

.page-preview {
