}

.topology-map {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.topology-center {
  grid-column: 1 / -1;
  border-radius: var(--r8);
  background: var(--ink);
  color: #ffffff;
  padding: 18px;
  display: grid;
  gap: 8px;
}

.topology-center strong,
.topology-node strong {
  font-size: 17px;
}

.topology-center span,
.topology-node span,
.flow-board-header span,
.snapshot-header span,
.connector-lane span,
.case-proof-card > span,
.flow-step span,
