.problem-signal span,
.video-strip,
.signal-strip span,
.proof-mini-grid strong {
  border: 1px solid var(--line);
  border-radius: var(--r8);
  background: #f7fafc;
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
  padding: 8px 10px;
}

.product-snapshot {
  display: grid;
  gap: 16px;
}

.mini-table,
.demo-summary-grid {
  display: grid;
  gap: 8px;
}

.mini-table-row,
.demo-summary-grid div,
.connector-lane {
  border: 1px solid var(--line);
  border-radius: var(--r8);
