.connector-flow {
  display: grid;
  gap: 12px;
}

.connector-lane.hub {
  background: var(--ink);
  color: #ffffff;
}

.connector-lane.hub span {
  color: rgba(255,255,255,.68);
}

.connection-tags {
  margin-top: 16px;
}

.connection-tags span,
.resource-signal-row span {
  min-height: 34px;
  font-size: 12px;
}

.data-flow-section {
  background: #f5f8fb;
}

.case-proof-card {
  display: grid;
  gap: 14px;
}

.proof-mini-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
